// Phase 1 step B (SPEC §23.5-§23.6): algorithm correctness against networkx 3.4.2 / graspologic-native reference
// values (fixtures/algo-reference.json, generated by explore/tools/algo-reference.py), Leiden guarantees, sampling
// accuracy, scopes (all / filter / ids), caching, HTTP + MCP. Ids B1..B12. ALGO_IMPL=wrong must make these fail.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import Graph from 'graphology';
import gmBetweenness from 'graphology-metrics/centrality/betweenness.js';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { algorithms as A } from '../shared/algorithms-impl.js';
import { loadConfig } from '../server/app.js';
import { buildMcpServer } from '../server/mcp-server.js';
import { resultJson } from '../server/connectors/mcp.js';
import { seedCore, CORE_NODES, CORE_LINKS } from './core-fixtures.js';
import { rng } from './core-rng.js';

const REF = JSON.parse(readFileSync(new URL('./fixtures/algo-reference.json', import.meta.url)));
const inputOf = g => ({ nodes: g.nodes, links: g.edges.map(([s, t]) => ({ id: `${s}|${t}`, s, t, directed: false })) });
const maxDiff = (a, b) => Math.max(...Object.keys(b).map(k => Math.abs((a[k] ?? NaN) - b[k])));
/** independent modularity (straight from the definition, over the edge list; parallel links add weight) */
function q(input, memb, gamma = 1) {
  const deg = {}; let m = 0, inside = 0; const K = {};
  for (const l of input.links) { if (l.s === l.t) continue; deg[l.s] = (deg[l.s] || 0) + 1; deg[l.t] = (deg[l.t] || 0) + 1; m++; if (memb[l.s] === memb[l.t]) inside++; }
  for (const id of input.nodes) K[memb[id]] = (K[memb[id]] || 0) + (deg[id] || 0);
  return inside / m - gamma * Object.values(K).reduce((s, x) => s + (x / (2 * m)) ** 2, 0);
}
function connectedWithin(input, ids) {
  const set = new Set(ids), adj = new Map(ids.map(i => [i, []]));
  for (const l of input.links) if (set.has(l.s) && set.has(l.t)) { adj.get(l.s).push(l.t); adj.get(l.t).push(l.s); }
  const seen = new Set([ids[0]]), st = [ids[0]]; while (st.length) for (const v of adj.get(st.pop())) if (!seen.has(v)) { seen.add(v); st.push(v); }
  return seen.size === ids.length;
}
const groups = values => { const g = new Map(); for (const [id, c] of Object.entries(values)) { if (!g.has(c)) g.set(c, []); g.get(c).push(id); } return [...g.values()]; };
function nmi(a, b) { // normalised mutual information of two labelings
  const ids = Object.keys(a), n = ids.length, ca = {}, cb = {}, cab = {};
  for (const i of ids) { ca[a[i]] = (ca[a[i]] || 0) + 1; cb[b[i]] = (cb[b[i]] || 0) + 1; const k = a[i] + '|' + b[i]; cab[k] = (cab[k] || 0) + 1; }
  const H = c => -Object.values(c).reduce((s, x) => s + (x / n) * Math.log(x / n), 0);
  let I = 0; for (const [k, x] of Object.entries(cab)) { const [p, r] = k.split('|'); I += (x / n) * Math.log((x * n) / (ca[p] * cb[r])); }
  return (2 * I) / (H(ca) + H(cb));
}
/** preferential-attachment graph (Barabási-Albert style, m links per new node): hubs make betweenness ranks meaningful */
function baGraph(n, m, seed) { const r = rng(seed), links = [], targets = []; for (let i = 0; i < n; i++) { const picked = new Set(); if (i > m) while (picked.size < m) picked.add(targets[Math.floor(r() * targets.length)]); else for (let j = 0; j < i; j++) picked.add(j); for (const j of picked) { links.push({ id: `e${links.length}`, s: `v${i}`, t: `v${j}` }); targets.push(i, j); } } return { nodes: Array.from({ length: n }, (_, i) => `v${i}`), links }; }
function randomGraph(n, m, seed) { const r = rng(seed), links = []; for (let j = 0; j < m; j++) { const a = Math.floor(r() * n), b = Math.floor(r() * n); if (a !== b) links.push({ id: `e${j}`, s: `v${a}`, t: `v${b}`, directed: false }); } return { nodes: Array.from({ length: n }, (_, i) => `v${i}`), links }; }

const eachRef = fn => { for (const [name, g] of Object.entries(REF.graphs)) fn(name, g, inputOf(g)); };
test('B1 degree equals networkx on karate / planted partition / les-mis', () => eachRef((name, g, input) => assert.deepEqual(A.runAlgorithm('degree', input).values, g.degree, name)));
test('B1p PageRank (undirected, alpha 0.85) equals networkx; karate leaders 33, 0, 32', () => {
  eachRef((name, g, input) => assert.ok(maxDiff(A.runAlgorithm('pagerank', input, { directed: false }).values, g.pagerank) < 1e-6, name));
  const k = A.runAlgorithm('pagerank', inputOf(REF.graphs.karate), { directed: false });
  assert.deepEqual(Object.entries(k.values).sort((a, b) => b[1] - a[1]).slice(0, 3).map(x => x[0]), ['33', '0', '32']);
});
test('B1b exact betweenness (normalised) equals networkx', () => eachRef((name, g, input) => { const bc = A.runAlgorithm('betweenness', input); assert.equal(bc.approximate, false); assert.ok(maxDiff(bc.values, g.betweenness) < 1e-9, name); }));
test('B1j Jaccard per link equals networkx jaccard_coefficient', () => eachRef((name, g, input) => assert.ok(maxDiff(A.runAlgorithm('jaccard', input).values, g.jaccard) < 1e-12, name)));

test('B2 directed PageRank (with a dangling and an isolated node) equals networkx', () => {
  const d = REF.directed_pagerank, input = { nodes: d.nodes, links: d.edges.map(([s, t], i) => ({ id: `d${i}`, s, t, directed: true })) };
  assert.ok(maxDiff(A.runAlgorithm('pagerank', input).values, d.pagerank) < 1e-6);
});

test('B3 Leiden reaches the known optimum on karate (0.4198, Brandes et al. 2008) and the graspologic value on every reference graph, for 10 seeds', () => {
  for (const [name, g] of Object.entries(REF.graphs)) {
    const input = inputOf(g);
    for (let seed = 1; seed <= 10; seed++) {
      const r = A.runAlgorithm('leiden', input, { seed });
      assert.ok(Math.abs(r.modularity - q(input, r.values)) < 1e-9, 'reported modularity is the real modularity');
      assert.ok(r.modularity >= g.leiden_graspologic_modularity.max - 1e-9, `${name} seed ${seed}: ${r.modularity} < ${g.leiden_graspologic_modularity.max}`);
    }
  }
  const r = A.runAlgorithm('leiden', inputOf(REF.graphs.karate));
  assert.equal(r.count, 4); assert.ok(Math.abs(r.modularity - REF.graphs.karate.optimum_modularity) < 1e-6);
});

test('B4 Leiden guarantee: every community is connected (karate, les-mis and 25 random sparse graphs); planted partition recovered exactly', () => {
  const graphs = [inputOf(REF.graphs.karate), inputOf(REF.graphs.lesmis), ...Array.from({ length: 25 }, (_, i) => randomGraph(300, 420 + i * 10, i + 1))];
  for (const input of graphs) {
    const r = A.runAlgorithm('leiden', input, { seed: 3 });
    for (const members of groups(r.values)) assert.ok(connectedWithin(input, members), `disconnected community of ${members.length}`);
    assert.ok(Math.abs(r.modularity - q(input, r.values)) < 1e-9);
  }
  const P = REF.graphs.planted_8x40, r = A.runAlgorithm('leiden', inputOf(P));
  assert.equal(r.count, 8); assert.ok(nmi(r.values, P.truth) > 0.999, `NMI ${nmi(r.values, P.truth)}`);
});

test('B5 Louvain: modularity within 3% of the optimum on karate and the graspologic value elsewhere; labels sorted by size', () => {
  for (const [name, g] of Object.entries(REF.graphs)) {
    const input = inputOf(g), r = A.runAlgorithm('louvain', input, { seed: 2 });
    assert.ok(Math.abs(r.modularity - q(input, r.values)) < 1e-9);
    assert.ok(r.modularity >= 0.97 * g.leiden_graspologic_modularity.max, `${name} ${r.modularity}`); // Louvain may stop in a local optimum (it has no refinement phase)
    for (let i = 1; i < r.sizes.length; i++) assert.ok(r.sizes[i] <= r.sizes[i - 1]);
  }
});

test('B6 sampled betweenness (5,000-node preferential-attachment graph, 400 sources) ranks like exact Brandes; exact agrees with graphology-metrics', () => {
  const input = baGraph(5000, 2, 9);
  const exact = A.runAlgorithm('betweenness', input, { exactMax: 100000 }), approx = A.runAlgorithm('betweenness', input, { samples: 400, seed: 4 });
  assert.equal(exact.approximate, false); assert.equal(approx.approximate, true); assert.equal(approx.samples, 400);
  const top = (v, k) => new Set(Object.entries(v).sort((a, b) => b[1] - a[1]).slice(0, k).map(x => x[0]));
  const te = top(exact.values, 50), ta = top(approx.values, 50); let both = 0; for (const x of ta) if (te.has(x)) both++;
  assert.ok(both >= 40, `top-50 overlap ${both}`);
  const ids = input.nodes, rank = v => { const r = {}; [...ids].sort((a, b) => v[a] - v[b] || (a < b ? -1 : 1)).forEach((id, i) => { r[id] = i; }); return r; };
  const ra = rank(exact.values), rb = rank(approx.values); let d2 = 0; for (const id of ids) d2 += (ra[id] - rb[id]) ** 2;
  const rho = 1 - (6 * d2) / (ids.length * (ids.length ** 2 - 1)); assert.ok(rho > 0.9, `Spearman ${rho}`);
  const se = Object.values(exact.values).reduce((a, b) => a + b, 0), sa = Object.values(approx.values).reduce((a, b) => a + b, 0);
  assert.ok(Math.abs(sa / se - 1) < 0.1, `total mass ratio ${sa / se}`);
  const L = inputOf(REF.graphs.lesmis), g = new Graph({ type: 'undirected' }); L.nodes.forEach(n => g.addNode(n)); L.links.forEach(l => g.mergeEdge(l.s, l.t));
  assert.ok(maxDiff(A.runAlgorithm('betweenness', L).values, gmBetweenness(g, { normalized: true })) < 1e-9);
});

test('B7 connected components equal networkx; isolated nodes are their own components, largest first', () => {
  for (const [name, g] of Object.entries(REF.graphs)) {
    const r = A.runAlgorithm('components', inputOf(g));
    assert.deepEqual(groups(r.values).map(c => c.sort()).sort((a, b) => b.length - a.length || (a[0] < b[0] ? -1 : 1)), g.components, name);
  }
  const input = { nodes: ['a', 'b', 'c', 'd', 'e', 'f'], links: [{ id: 1, s: 'a', t: 'b' }, { id: 2, s: 'b', t: 'c' }, { id: 3, s: 'd', t: 'e' }] };
  const r = A.runAlgorithm('components', input);
  assert.equal(r.count, 3); assert.deepEqual(r.sizes, [3, 2, 1]); assert.equal(r.values.f, 2); assert.equal(r.values.a, 0);
});

test('B8 shortest_path: hop distances equal BFS, path is shortest; weighted (Dijkstra) picks the cheaper route', () => {
  const input = inputOf(REF.graphs.karate), r = A.runAlgorithm('shortest_path', input, { source: '16', target: '25' });
  const adj = new Map(input.nodes.map(n => [n, []])); for (const l of input.links) { adj.get(l.s).push(l.t); adj.get(l.t).push(l.s); }
  const d = { 16: 0 }, fr = ['16']; while (fr.length) { const u = fr.shift(); for (const v of adj.get(u)) if (!(v in d)) { d[v] = d[u] + 1; fr.push(v); } }
  assert.deepEqual(r.values, d); assert.equal(r.path.length - 1, d['25']); assert.equal(r.distance, d['25']);
  const w = { nodes: ['a', 'b', 'c', 'd'], links: [{ id: 'ab', s: 'a', t: 'b', w: 10 }, { id: 'bd', s: 'b', t: 'd', w: 10 }, { id: 'ac', s: 'a', t: 'c', w: 1 }, { id: 'cd', s: 'c', t: 'd', w: 1 }, { id: 'ad', s: 'a', t: 'd', w: 50 }] };
  const wr = A.runAlgorithm('shortest_path', w, { source: 'a', target: 'd', weightProperty: 'cost' });
  assert.deepEqual(wr.path, ['a', 'c', 'd']); assert.equal(wr.distance, 2);
  assert.throws(() => A.runAlgorithm('shortest_path', input, { source: 'nope' }), /not in the scope/);
});

test('B9 Jaccard top-k similar to one node equals brute force', () => {
  const input = inputOf(REF.graphs.karate), r = A.runAlgorithm('jaccard', input, { node: '0', k: 5 });
  const N = new Map(input.nodes.map(n => [n, new Set()])); for (const l of input.links) { N.get(l.s).add(l.t); N.get(l.t).add(l.s); }
  const J = (a, b) => { const i = [...a].filter(x => b.has(x)).length; return i / new Set([...a, ...b]).size; };
  const all = input.nodes.filter(v => v !== '0' && [...N.get('0')].some(u => N.get(u).has(v))).map(v => [v, J(N.get('0'), N.get(v))]).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, 5);
  assert.deepEqual(Object.entries(r.values).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)), all);
});

// ---------------------------------------------------------------- server: scopes, cache, HTTP, MCP
let app, base, dir;
before(async () => {
  const { startCombined } = await import('../combined.js');
  dir = mkdtempSync(join(tmpdir(), 'sgx-algo-'));
  const cfg = loadConfig(join(dir, 'none.json'));
  app = await startCombined({ port: 0, dataDir: dir, log: null, config: { ...cfg, streams: ['external', 'hr'], access: { ...cfg.access, sources: { hr: { read: ['role:hr'] } } } } });
  base = `http://127.0.0.1:${app.port}`;
  await seedCore(app.ex);
  const hr = app.ex.producer('hr'); hr.push('node.upsert', { id: 'hr:x', type: 'Person', properties: { risk: 99 } }); hr.push('link.upsert', { id: 'hr:l', type: 'KNOWS', fromId: 'c0', toId: 'hr:x' }); await hr.flush();
});
after(async () => { await app?.close(); if (dir) rmSync(dir, { recursive: true, force: true }); });
const run = async body => { const r = await fetch(`${base}/api/explore/algo/run`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }); return r.json(); };

test('B10 scopes over HTTP: all / filter (types, where, hidden link types) / ids; never includes unreadable sources; results recompute when the filter changes', async () => {
  const all = await run({ algo: 'degree', scope: { kind: 'all' } });
  assert.equal(all.scope.nodes, CORE_NODES.length); assert.ok(!('hr:x' in all.values)); assert.equal(all.values.c0, 4);
  const persons = await run({ algo: 'degree', scope: { kind: 'filter', types: ['Person'] } });
  assert.deepEqual(Object.keys(persons.values).sort(), CORE_NODES.filter(n => n[1] === 'Person').map(n => n[0]).sort());
  assert.equal(persons.values.c0, 3, 'OWNS -> Account is outside the scope');
  const risky = await run({ algo: 'degree', scope: { kind: 'filter', where: [{ property: 'risk', op: 'gte', value: 50 }] } });
  assert.deepEqual(Object.keys(risky.values).sort(), ['a1', 'a3', 'acc1', 'acc2', 'b1']);
  assert.deepEqual(risky.values, { a1: 2, a3: 1, acc1: 1, acc2: 1, b1: 1 });
  const noKnows = await run({ algo: 'components', scope: { kind: 'filter', hiddenLinkTypes: ['KNOWS'] } });
  assert.equal(noKnows.values.a1 === noKnows.values.c0, false);
  const ids = await run({ algo: 'pagerank', params: { directed: false }, scope: { kind: 'ids', ids: ['c0', 'a1', 'a2', 'hr:x'] } });
  assert.deepEqual(Object.keys(ids.values).sort(), ['a1', 'a2', 'c0'], 'unreadable ids are dropped');
  assert.ok(Math.abs(ids.values.c0 - 0.4864864864864865) < 1e-6, `star of 3: centre PageRank ${ids.values.c0}`);
});

test('B11 cache: the same request is served from cache until the graph changes; result endpoint returns values by id', async () => {
  const a = await run({ algo: 'louvain', scope: { kind: 'all' } }), b = await run({ algo: 'louvain', scope: { kind: 'all' } });
  assert.equal(b.cached, true); assert.equal(a.runId, b.runId);
  const p = app.ex.producer('external'); p.push('link.upsert', { id: 'cache:l', type: 'KNOWS', fromId: 'z1', toId: 'd1' }); await p.flush();
  const c = await run({ algo: 'louvain', scope: { kind: 'all' } }); assert.ok(!c.cached); assert.notEqual(c.runId, a.runId);
  const r = await (await fetch(`${base}/api/explore/algo/result/${c.runId}?ids=c0,a1`)).json();
  assert.deepEqual(Object.keys(r.values).sort(), ['a1', 'c0']);
  assert.equal((await fetch(`${base}/api/explore/algo/result/nope`)).status, 404);
  assert.equal((await fetch(`${base}/api/explore/algo/run`, { method: 'POST', body: JSON.stringify({ algo: 'nope' }) })).status, 400);
});

test('B12 MCP: list_algorithms, run_algorithm (top-k + scope), get_algorithm_result (ids, community members)', async () => {
  const server = buildMcpServer(app.ex, { actAs: null }), [x, y] = InMemoryTransport.createLinkedPair(), client = new Client({ name: 't', version: '1' });
  await Promise.all([server.connect(x), client.connect(y)]);
  const call = async (name, args) => { const r = await client.callTool({ name, arguments: args }); return r.isError ? { error: r.content[0].text } : resultJson(r); };
  try {
    const l = await call('list_algorithms', {}); assert.deepEqual(l.algorithms.map(a => a.name).sort(), ['betweenness', 'components', 'degree', 'jaccard', 'leiden', 'louvain', 'pagerank', 'shortest_path']);
    const d = await call('run_algorithm', { algo: 'degree', top: 2 });
    assert.deepEqual(d.top.map(t => t.id), ['c0', 'a1']); assert.ok(!('values' in d));
    const lei = await call('run_algorithm', { algo: 'leiden', scope: { kind: 'filter', types: ['Person'] } });
    const members = await call('get_algorithm_result', { runId: lei.runId, community: 0 });
    assert.ok(Object.keys(members.values).length === lei.sizes[0]);
    const byId = await call('get_algorithm_result', { runId: d.runId, ids: ['b1', 'hr:x'] });
    assert.deepEqual(byId.values, { b1: 3 });
    assert.match((await call('run_algorithm', { algo: 'shortest_path', params: { source: 'hr:x' } })).error, /not in the scope/);
  } finally { await client.close(); await server.close(); }
});
